function compute(inputs) {
  const eta = inputs.eta;
  const theta0 = inputs.theta0;
  const steps = 20;
  const thetas = [theta0];
  const losses = [theta0*theta0];
  let theta = theta0;
  for (let i = 0; i < steps; i++) {
    const grad = 2 * theta;
    theta = theta - eta * grad;
    thetas.push(theta);
    losses.push(theta*theta);
  }
  const finalTheta = thetas[thetas.length-1];
  const finalLoss = losses[losses.length-1];
  const converged = Math.abs(finalTheta) < 1e-6;
  const diverged = Math.abs(finalTheta) > 1e6;
  let insight = '';
  if (eta < 1) {
    insight = 'Converges to 0 because |1-2\u03b7| < 1.';
  } else if (eta === 1) {
    insight = 'Oscillates between \u03b8 and -\u03b8 forever.';
  } else {
    insight = 'Diverges because |1-2\u03b7| > 1.';
  }
  if (eta === 0.5) {
    insight = 'Reaches the minimum in one step because 1-2\u03b7 = 0.';
  }
  const tableRows = [];
  for (let i = 0; i <= steps; i++) {
    tableRows.push([i, thetas[i], losses[i]]);
  }
  return {
    theta: thetas,
    loss: losses,
    finalTheta: finalTheta,
    finalLoss: finalLoss,
    converged: converged,
    diverged: diverged,
    insight: insight,
    table: { columns: ['Step', '\u03b8', 'Loss'], rows: tableRows }
  };
}
